record.field:
{
    "properties": {
        "activity_type": {
            "type": "string",
            "description": "Type of activity: call, email, meeting, or todo"
        },
        "summary": {
            "type": "string",
            "description": "Short summary / title of the activity"
        },
        "date_deadline": {
            "type": "string",
            "description": "Deadline date in YYYY-MM-DD format"
        },
        "note": {
            "type": "string",
            "description": "Additional notes or description for the activity (optional)"
        },
        "user_id": {
            "type": "number",
            "description": "ID of the user to assign the activity to (optional, defaults to current user)"
        }
    },
    "required": ["activity_type", "summary", "date_deadline"],
    "type": "object"
}
